// Using the react-error-boundary package's ErrorBoundary component.
import { useEffect, useState } from "react";
import { ErrorBoundary } from "react-error-boundary";

function LessonFallback({ error, resetErrorBoundary }) {
  const [incidentId] = useState(() => crypto.randomUUID().slice(0, 8));
  useEffect(() => {
    sendToLogs({ id: incidentId, message: error.message });   // details go to logs.
  }, [incidentId, error]);
  return (
    <section role="alert">
      <h2>This lesson couldn't be shown</h2>
      <p>Something went wrong on our side. Reference: {incidentId}.</p>
      <button type="button" onClick={resetErrorBoundary}>Try again</button>
    </section>
  );
}

<ErrorBoundary FallbackComponent={LessonFallback} resetKeys={[lessonId]}>
  <LessonPage lessonId={lessonId} />
</ErrorBoundary>
```

| Error happens in | Caught by |
|---|---|
| rendering a child. | the nearest error boundary. |
| an event handler. | your try/catch. |
| a fetch or promise. | .catch or try/await, stored as error state. |
| the boundary itself. | the next boundary above. |

